+    public void pushToStack(int serviceId, String videoUrl, String name) {
+        if (DEBUG) {
+            Log.d(TAG, "pushToStack() called with: serviceId = ["
+                    + serviceId + "], videoUrl = [" + videoUrl + "], name = [" + name + "]");
+        }
+
+        if (stack.size() > 0
