+            if (subscribeButtonMonitor != null) subscribeButtonMonitor.dispose();
+
+            if (subscriptionEntities.isEmpty()) {
+                if (DEBUG) Log.d(TAG, "No subscription to this channel!");
+                SubscriptionEntity channel = new SubscriptionEntity();
